@if($type!=='payments')<template id="line-template">{!! preg_replace('/lines\[0\]/','lines[__INDEX__]',preg_replace('/value="[^"]*"/','value=""',view('purchases.line-template',compact('accounts'))->render())) !!}</template><script>const lines=document.querySelector('#lines'),template=document.querySelector('#line-template');function totals(){let total=0;lines.querySelectorAll('.purchase-line').forEach(row=>{const n=f=>Number.parseFloat(row.querySelector('[name*="['+f+']"]')?.value||0);total+=n('quantity')*n('unit_price')-n('discount')});document.querySelector('#document-total').textContent=total.toFixed(2)+' {{$company->baseCurrency->code}}'}document.querySelector('#add-line').onclick=()=>{lines.insertAdjacentHTML('beforeend',template.innerHTML.replaceAll('__INDEX__',Date.now()));totals()};lines.addEventListener('click',e=>{if(e.target.classList.contains('remove-line'))e.target.closest('.purchase-line').remove();totals()});lines.addEventListener('input',totals);totals()</script>@endif @endsection
